function UpdateProfile(){ 

    const baseUrl = (process.env.REACT_APP_API_BASE_URL || "http://localhost:4000") + "/users/";
    const {userCredentials, setUserCredentials} = useContext(AppContext)
    const navigate = useNavigate()



    async function handleSubmit(event){
        event.preventDefault()

	const formData = new FormData(event.target)
	const user     = Object.fromEntries(formData.entries())

       if(!user.firstname || !user.lastname || !user.email) {
           alert("Please fill all the require fields!")
           return
       }

       try{
            const response = await fetch(baseUrl + userCredentials.user.id, {
                 method: "PATCH",
		 headers: {
                        "Content-Type": "application/json",
			"Authorization": "Bearer " + userCredentials.accessToken
		    },
		    body: JSON.stringify(user)
	    })
               // The ({...userCredentials, user: data}) in this context uses '...' to say copy userCredentials
	       // This allows us to copy this object type of userCredentials and then we update that copies user with
	       // the data we got from the json server-> this updates the database!
	       const data = await response.json()
	       if(response.ok){
	           alert("User Profile updated correctly!")
		   console.log("server response: ", data)
                   setUserCredentials({...userCredentials, user: data})
	       }
	       else if(response.status === 401){
                   // disconnect and redirect -> unauthorized users get bounced at the door
		   setUserCredentials(null)
		   navigate("/auth/login")
	       }
	       else{
                    alert("Unable to update the profile: " + data)
	       }
       }
       catch(error){
           alert("Unable to connect to the server!")
       }
    }




    return(
        <form onSubmit={handleSubmit}>

            <div className="row mb-3">
	        <label className="col-sm-4 col-form-label">First Name</label>
	        <div className="col-sm-8">
	             <input className="form-control" name ="firstname" defaultValue={userCredentials.user.firstname} />
	        </div>
	    </div>

            <div className="row mb-3">
                <label className="col-sm-4 col-form-label">Last Name</label>
                <div className="col-sm-8">
                     <input className="form-control" name ="lastname" defaultValue={userCredentials.user.lastname}/>
                </div>
            </div>

	    <div className="row mb-3">
                <label className="col-sm-4 col-form-label">Email</label>
                <div className="col-sm-8">
                     <input className="form-control" name ="email" defaultValue={userCredentials.user.email}/>
                </div>
            </div>

	    <div className="row mb-3">
                <label className="col-sm-4 col-form-label">Phone</label>
                <div className="col-sm-8">
                     <input className="form-control" name ="phone" defaultValue={userCredentials.user.phone}/>
                </div>
            </div>

	    <div className="row mb-3">
                <label className="col-sm-4 col-form-label">Address</label>
